import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  const cleanups = [];

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ---- Backdrop plane (engineered gradient: surface -> ink) ----
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.113),
    smoothstep(float(0.0), float(1.0), uv().y)
  );
  backdropMat.transparent = false;
  const backdrop = new Mesh(new THREE.PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  cleanups.push(() => { backdropMat.dispose(); backdrop.geometry.dispose(); });

  // ---- Image plane (CTA hero isolated) ----
  let imageMesh = null;
  let imageMat = new MeshBasicNodeMaterial({ transparent: true });

  // subtle grain via time-driven hash on uv
  const grain = float(0.015).mul(
    smoothstep(float(0.48), float(0.52), uv().x.add(uv().y).add(time.mul(0.1)).fract()).sub(float(0.5)).abs()
  );
  imageMat.colorNode = mix(
    vec3(1.0, 1.0, 1.0),
    vec3(0.93, 0.93, 0.95),
    grain
  );

  const imageGeo = new THREE.PlaneGeometry(3.2, 2.0);
  imageMesh = new Mesh(imageGeo, imageMat);
  imageMesh.position.set(0, -0.2, 0.1);
  group.add(imageMesh);

  // load texture
  const texUrl = config.imageUrl || config.intent?.visualSpec?.imageUrl;
  if (texUrl) {
    ctx.textureLoader.loadTexture(texUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      imageMat.map = tex;
      imageMat.needsUpdate = true;
    });
  }
  cleanups.push(() => { imageMat.dispose(); imageGeo.dispose(); });

  // ---- Accent strip (signal red <=10% frame) ----
  const accentMat = new MeshBasicNodeMaterial({ color: new THREE.Color(colors.accent) });
  const accentBar = new Mesh(new THREE.PlaneGeometry(0.08, 0.04), accentMat);
  accentBar.position.set(-1.55, 1.15, 0.05);
  group.add(accentBar);
  cleanups.push(() => { accentMat.dispose(); accentBar.geometry.dispose(); });

  // ---- Text: "Pricing" headline ----
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = textItems.find((t) => t.role === 'headline') ?? textItems[0];
  if (headline) {
    const txt = ctx.fontAtlas.createText(String(headline.text), {
      fontSize: headline.typography?.fontSize ?? 96,
      color: colors.paper,
      align: 'left',
    });
    txt.position.set(-1.6, 0.95, 0.12);
    group.add(txt);
  }

  // ---- Subtle entrance (static composition, weighted-settle) ----
  group.scale.set(0.98, 0.98, 1);
  const tl = gsap.timeline();
  tl.to(group.scale, { x: 1, y: 1, duration: 0.9, ease: 'power4.out', overwrite: true });
  tl.from(group.position, { y: 0.3, duration: 0.7, ease: 'power3.out' }, 0);
  cleanups.push(() => tl.kill());

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    cleanups.forEach((fn) => fn());
    cleanups.length = 0;
  };

  return group;
}
